source = '''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)

    # Project the rectangle horizontally. A marker on a row blocks that
    # side, so the color extends from the rectangle away from the marker.
    for r in range(r0, r1 + 1):
        markers = [c for c in range(w) if grid[r][c] not in (0, 2)]
        if not markers:
            spans = [(0, w - 1)]
        elif min(markers) < c0:
            spans = [(c1 + 1, w - 1)]
        else:
            spans = [(0, c0 - 1)]
        for lo, hi in spans:
            for c in range(lo, hi + 1):
                if out[r][c] == 0:
                    out[r][c] = 2

    # Project the rectangle vertically. Marked columns are omitted on the
    # side of the rectangle where the marker lies.
    blocked_above = {c for r in range(r0) for c in range(w) if grid[r][c] not in (0, 2)}
    blocked_below = {c for r in range(r1 + 1, h) for c in range(w) if grid[r][c] not in (0, 2)}
    for c in range(c0, c1 + 1):
        if c not in blocked_above:
            for r in range(r0):
                if out[r][c] == 0:
                    out[r][c] = 2
        if c not in blocked_below:
            for r in range(r1 + 1, h):
                if out[r][c] == 0:
                    out[r][c] = 2
    return out
'''
